def compute(vars):
    revenue_2018 = vars["v1"]
    revenue_2017 = vars["v2"]

    if revenue_2017 == 0:
        return None

    ratio = revenue_2018 / revenue_2017
    return {
        "value": ratio,
        "trace": {
            "revenue_2018": revenue_2018,
            "revenue_2017": revenue_2017,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
